using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

public static class NemoBoundaryVerifier
{
    [Serializable] public class PixelResult {public int samples,unsupported,worldExtentSamples;public Vector2[] failures;public int tolerancePixels=4;public float worldTolerance=4f/64;}
    [Serializable] public class MotionResult {public Vector2 point,start,end;public string kind;public bool pass,touched;}
    [Serializable] public class SeedResult {public int seed,walls,visibleLowObjects,trees,gapProbeSkips,gapOtherObstacleSkips,openGroundProbeSkips;public bool success;public PixelResult pixels;public MotionResult[] movement;public string[] errors;}
    [Serializable] public class Report {public bool success;public SeedResult[] seeds;public string scope;}
    class Pixels
    {
        readonly Dictionary<string,Color32[]> data=new Dictionary<string,Color32[]>();readonly Dictionary<string,int> widths=new Dictionary<string,int>();
        readonly Dictionary<Vector2Int,List<SpriteRenderer>> cells=new Dictionary<Vector2Int,List<SpriteRenderer>>();
        public Pixels(IEnumerable<SpriteRenderer> renders){foreach(var r in renders){if(r==null||r.sprite==null||r.color.a<.85f)continue;var b=r.bounds;for(int x=Mathf.FloorToInt(b.min.x/2);x<=Mathf.FloorToInt(b.max.x/2);x++)for(int y=Mathf.FloorToInt(b.min.y/2);y<=Mathf.FloorToInt(b.max.y/2);y++){var key=new Vector2Int(x,y);if(!cells.TryGetValue(key,out var list))cells[key]=list=new List<SpriteRenderer>();list.Add(r);}string path=AssetDatabase.GetAssetPath(r.sprite);if(data.ContainsKey(path))continue;var texture=new Texture2D(2,2,TextureFormat.RGBA32,false);texture.LoadImage(File.ReadAllBytes(path));widths[path]=texture.width;data[path]=texture.GetPixels32();UnityEngine.Object.DestroyImmediate(texture);}}
        bool Opaque(SpriteRenderer r,Vector2 point,int tolerance){var local=r.transform.InverseTransformPoint(point);var sprite=r.sprite;int x=Mathf.FloorToInt(local.x*sprite.pixelsPerUnit+sprite.pivot.x),y=Mathf.FloorToInt(local.y*sprite.pixelsPerUnit+sprite.pivot.y);if(r.flipX)x=(int)sprite.rect.width-1-x;if(r.flipY)y=(int)sprite.rect.height-1-y;string path=AssetDatabase.GetAssetPath(sprite);int width=widths[path];var pixels=data[path];
            for(int dy=-tolerance;dy<=tolerance;dy++)for(int dx=-tolerance;dx<=tolerance;dx++){if(dx*dx+dy*dy>tolerance*tolerance)continue;int px=x+dx,py=y+dy;if(px<0||py<0||px>=sprite.rect.width||py>=sprite.rect.height)continue;int at=((int)sprite.rect.y+py)*width+(int)sprite.rect.x+px;if(at>=0&&at<pixels.Length&&pixels[at].a>=160)return true;}return false;}
        public bool Covered(Vector2 p,int tolerance=4){var key=new Vector2Int(Mathf.FloorToInt(p.x/2),Mathf.FloorToInt(p.y/2));return cells.TryGetValue(key,out var list)&&list.Any(r=>Opaque(r,p,tolerance));}
    }
    static IEnumerable<(Vector2 p,Vector2 normal)> Samples(NemoBoundaryWall wall,float spacing){for(int k=1;k<wall.points.Length;k++){var a=wall.points[k-1];var b=wall.points[k];var t=(b-a).normalized;var n=new Vector2(-t.y,t.x);int steps=Mathf.Max(1,Mathf.CeilToInt(Vector2.Distance(a,b)/spacing));for(int i=0;i<steps;i++)yield return (Vector2.Lerp(a,b,(float)i/steps),n);}var d=(wall.points.Last()-wall.points[wall.points.Length-2]).normalized;yield return (wall.points.Last(),new Vector2(-d.y,d.x));}
    static IEnumerable<(Vector2 p,Vector2 normal)> GapSamples(NemoBoundary boundary,NemoBoundaryWall wall){float cursor=0;for(int k=1;k<wall.points.Length;k++){var a=wall.points[k-1];var b=wall.points[k];float length=Vector2.Distance(a,b);var d=(b-a).normalized;while(cursor<=length){yield return (Vector2.Lerp(a,b,length==0?0:cursor/length),new Vector2(-d.y,d.x));cursor+=.65f;}cursor-=length;}}
    static PixelResult Correspondence(NemoBoundary boundary)
    {
        var pixels=new Pixels(boundary.Supports.SelectMany(s=>s.visuals));var failed=new List<Vector2>();int samples=0,unsupported=0,extent=0;
        void Check(Vector2 point){if(point.x<.065f||point.x>143.935f||point.y<.065f||point.y>107.935f){extent++;return;}samples++;if(pixels.Covered(point))return;unsupported++;if(failed.Count<100)failed.Add(point);}
        foreach(var wall in boundary.Walls){foreach(var sample in Samples(wall,.10f)){Check(sample.p);if(wall.collider.edgeRadius>0){Check(sample.p+sample.normal*wall.collider.edgeRadius);Check(sample.p-sample.normal*wall.collider.edgeRadius);}}if(wall.collider.edgeRadius>0)foreach(var end in new[]{wall.points[0],wall.points.Last()})for(int k=0;k<12;k++)Check(end+new Vector2(Mathf.Cos(k*Mathf.PI/6),Mathf.Sin(k*Mathf.PI/6))*wall.collider.edgeRadius);}
        foreach(var body in boundary.GetComponentsInChildren<BoxCollider2D>()){var b=body.bounds;var min=(Vector2)b.min;var max=(Vector2)b.max;foreach(var edge in new[]{new[]{min,new Vector2(max.x,min.y)},new[]{new Vector2(max.x,min.y),max},new[]{max,new Vector2(min.x,max.y)},new[]{new Vector2(min.x,max.y),min}}){int count=Mathf.Max(1,Mathf.CeilToInt(Vector2.Distance(edge[0],edge[1])/.10f));for(int i=0;i<=count;i++)Check(Vector2.Lerp(edge[0],edge[1],(float)i/count));}Check(b.center);}
        return new PixelResult{samples=samples,unsupported=unsupported,worldExtentSamples=extent,failures=failed.ToArray()};
    }
    static bool Free(NemoWalk walk,Vector2 point){var capsule=walk.Actor.GetComponent<CapsuleCollider2D>();return !Physics2D.OverlapCapsuleAll(point,capsule.size,CapsuleDirection2D.Vertical,0).Any(c=>c!=capsule&&c.enabled&&!c.isTrigger);}
    static MotionResult Move(NemoWalk walk,Vector2 point,Vector2 normal,bool shouldStop){var capsule=walk.Actor.GetComponent<CapsuleCollider2D>();var boundaryColliders=walk.Map.Boundary.GetComponentsInChildren<Collider2D>();var result=new MotionResult{point=point,start=point+normal*.9f,kind=shouldStop?"intended-area-forest-edge-stop":"open-block-exit-crossing"};walk.Teleport(result.start);var target=point-normal*.8f;for(int i=0;i<60;i++){var d=target-walk.BodyCenter;walk.Actor.linearVelocity=d.normalized*Mathf.Min(3,d.magnitude/.02f);Physics2D.Simulate(.02f);result.touched|=boundaryColliders.Any(c=>capsule.IsTouching(c));}walk.Actor.linearVelocity=Vector2.zero;result.end=walk.BodyCenter;result.pass=shouldStop?result.touched&&walk.Map.Boundary.WalkRegion.Contains(result.end)&&Vector2.Distance(result.end,target)>.25f:Vector2.Distance(result.end,target)<.06f&&!result.touched;return result;}
    public static void Baseline()
    {
        EditorSceneManager.OpenScene(NemoRiverVerifier.ScenePath);var walk=UnityEngine.Object.FindAnyObjectByType<NemoWalk>();var pixels=new Pixels(walk.Map.World.GetComponentsInChildren<SpriteRenderer>());var bad=new List<Vector2>();Vector2 chosen=Vector2.zero,normal=Vector2.up;int count=0;foreach(var wall in walk.Map.Boundary.Walls)foreach(var sample in Samples(wall,.25f)){count++;if(pixels.Covered(sample.p))continue;bad.Add(sample.p);if(chosen==Vector2.zero&&sample.p.x>2&&sample.p.x<142&&sample.p.y>2&&sample.p.y<106&&Free(walk,sample.p+sample.normal*.9f)&&Free(walk,sample.p-sample.normal*.9f)){chosen=sample.p;normal=sample.normal;}}
        var before=walk.BodyCenter;Physics2D.simulationMode=SimulationMode2D.Script;MotionResult motion=null;try{if(chosen!=Vector2.zero){motion=Move(walk,chosen,normal,true);NemoBuilder.Capture(walk.View,chosen,NemoWalk.NormalCameraSize,Path.Combine(NemoBuilder.Evidence,"before-v3-ghost-wall-normal.png"));CaptureOverlay(walk,chosen,"before-v3-ghost-wall-overlay.png");}}finally{Physics2D.simulationMode=SimulationMode2D.FixedUpdate;walk.Teleport(before);}
        File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"before-v3-visual-collision-mismatch.json"),JsonUtility.ToJson(new BaselineResult{wallSamples=count,unsupportedPixels=bad.Count,chosen=chosen,motion=motion,scope="Actual v3 saved Scene in isolated v4 copy. Samples reject shadow-only coverage; compare exact native PNG alpha with four-pixel tolerance. Open-ground contact independently confirmed by actual Physics2D."},true));
    }
    [Serializable]class BaselineResult{public int wallSamples,unsupportedPixels;public Vector2 chosen;public MotionResult motion;public string scope;}
    static void CaptureOverlay(NemoWalk walk,Vector2 focus,string name)
    {
        var root=new GameObject("Temporary actual Collider display");var material=new Material(Shader.Find("Sprites/Default"));
        void Line(Vector2[] points,Color color,float width){var go=new GameObject("Actual Collider outline");go.transform.SetParent(root.transform);var line=go.AddComponent<LineRenderer>();line.sharedMaterial=material;line.startColor=line.endColor=color;line.startWidth=line.endWidth=width;line.sortingOrder=32750;line.positionCount=points.Length;line.SetPositions(points.Select(p=>new Vector3(p.x,p.y,-.01f)).ToArray());}
        foreach(var wall in walk.Map.Boundary.Walls){Line(wall.points,Color.green,.025f);var plus=new List<Vector2>();var minus=new List<Vector2>();foreach(var s in Samples(wall,.2f)){plus.Add(s.p+s.normal*wall.collider.edgeRadius);minus.Add(s.p-s.normal*wall.collider.edgeRadius);}Line(plus.ToArray(),Color.green,.012f);Line(minus.ToArray(),Color.green,.012f);}
        foreach(var body in walk.Map.Boundary.GetComponentsInChildren<BoxCollider2D>()){var b=body.bounds;Line(new[]{new Vector2(b.min.x,b.min.y),new Vector2(b.max.x,b.min.y),new Vector2(b.max.x,b.max.y),new Vector2(b.min.x,b.max.y),new Vector2(b.min.x,b.min.y)},Color.yellow,.018f);}
        NemoBuilder.Capture(walk.View,focus,NemoWalk.NormalCameraSize,Path.Combine(NemoBuilder.Evidence,name));UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(material);
    }
    public static void InspectAll()
    {
        var results=new List<SeedResult>();foreach(int seed in new[]{0,17,42,99,20261011}){var issues=new List<string>();var result=new SeedResult{seed=seed};var movements=new List<MotionResult>();
            try{EditorSceneManager.OpenScene(seed==0?NemoRiverVerifier.ScenePath:"Assets/NemoBlocks/Scenes/RiverSeeds/NemoRiverSeed"+seed+".unity");var walk=UnityEngine.Object.FindAnyObjectByType<NemoWalk>();var boundary=walk.Map.Boundary;if(boundary.Supports==null||boundary.Supports.Length==0)throw new Exception("Missing visible natural forest ownership");result.walls=boundary.Walls.Length;result.visibleLowObjects=boundary.NativeBarrierCount;result.trees=boundary.NativeTreeCount;result.pixels=Correspondence(boundary);if(result.pixels.unsupported!=0)issues.Add("Boundary Collider samples lack visible opaque Sprite support: "+result.pixels.unsupported);
                Physics2D.simulationMode=SimulationMode2D.Script;var capsule=walk.Actor.GetComponent<CapsuleCollider2D>();var candidates=new List<(Vector2 p,Vector2 n)>();foreach(var wall in boundary.Walls){foreach(var sample in GapSamples(boundary,wall)){if(sample.p.x<1||sample.p.x>143||sample.p.y<1||sample.p.y>107)continue;foreach(int side in new[]{1}){var n=sample.normal*side;if(!boundary.WalkRegion.Contains(sample.p+n*.9f)||boundary.WalkRegion.Contains(sample.p-n*.8f))continue;if(!Free(walk,sample.p+n*.9f)){result.gapProbeSkips++;continue;}bool blocked=Enumerable.Range(0,12).Any(k=>Physics2D.OverlapCapsuleAll(sample.p+n*Mathf.Lerp(.90f,.30f,k/11f),capsule.size,CapsuleDirection2D.Vertical,0).Any(c=>c!=capsule&&c.enabled&&!c.isTrigger&&!c.transform.IsChildOf(boundary.transform)));if(blocked){result.gapOtherObstacleSkips++;continue;}candidates.Add((sample.p,n));}}}
                int total=Mathf.Min(128,candidates.Count);for(int i=0;i<total;i++){var c=candidates[Mathf.FloorToInt((float)i*candidates.Count/total)];movements.Add(Move(walk,c.p,c.n,true));}
                var clear=new List<Vector2>();foreach(var exitGate in boundary.Gates){if(clear.Count>=24)break;var item=exitGate.port;var tangent=(exitGate.end-exitGate.start).normalized;var normal=new Vector2(-tangent.y,tangent.x);bool blocked=Enumerable.Range(0,17).Any(i=>!Free(walk,Vector2.Lerp(item+normal*.9f,item-normal*.8f,i/16f)));if(blocked){result.openGroundProbeSkips++;continue;}clear.Add(item);movements.Add(Move(walk,item,normal,false));}
                if(total==0)issues.Add("No accessible thicket contact probes");if(clear.Count==0)issues.Add("No clear block exit crossing probes");if(movements.Any(m=>!m.pass))issues.Add("Boundary movement failed");
                var contact=movements.First(m=>m.kind=="intended-area-forest-edge-stop");walk.Teleport(contact.end);NemoBuilder.Capture(walk.View,contact.point,NemoWalk.NormalCameraSize,Path.Combine(NemoBuilder.Evidence,"boundary-seed-"+seed+"-normal.png"));CaptureOverlay(walk,contact.point,"boundary-seed-"+seed+"-overlay.png");var gate=boundary.Gates.First();walk.Teleport(gate.port);NemoBuilder.Capture(walk.View,gate.port,NemoWalk.NormalCameraSize,Path.Combine(NemoBuilder.Evidence,"boundary-seed-"+seed+"-gate.png"));CaptureOverlay(walk,gate.port,"boundary-seed-"+seed+"-gate-overlay.png");walk.Teleport(walk.Map.Plan.parcels[0].hub);NemoBuilder.Capture(walk.View,new Vector2(72,54),56,Path.Combine(NemoBuilder.Evidence,"boundary-seed-"+seed+"-overview.png"),1728,1296);
            }catch(Exception e){issues.Add(e.ToString());Debug.LogException(e);}finally{Physics2D.simulationMode=SimulationMode2D.FixedUpdate;result.movement=movements.ToArray();result.errors=issues.ToArray();result.success=issues.Count==0;results.Add(result);File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"boundary-seed-"+seed+"-alignment.json"),JsonUtility.ToJson(result,true));Debug.Log("NEMO_BOUNDARY_ALIGNMENT "+seed+" "+result.success);}}
        File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"boundary-alignment-verification.json"),JsonUtility.ToJson(new Report{success=results.Count==5&&results.All(r=>r.success),seeds=results.ToArray(),scope="All final saved boundary EdgeCollider centre/radius samples and native trunk BoxCollider outlines compared with exact source PNG alpha, four-pixel (0.0625 world) tolerance for tiny leaf holes. Stratified real Physics2D gap contacts and clear block exit crossings. Gates, roads, approaches, water and both bridges additionally covered by NemoRiverVerifier.Full. Manual keys and Player build excluded."},true));EditorSceneManager.OpenScene(NemoRiverVerifier.ScenePath);
    }
}
